#!/usr/bin/env bash
set -euo pipefail
mode=${1:?mode}; results=${2:?results}; artifacts=${3:?artifacts}; count=${4:?count}; run_id=${5:?run id}; dir="$results/$mode-requests"; mkdir -p "$dir"
wait_artifact(){ local id=$1; for _ in $(seq 1 200);do [[ -f "$artifacts/$id.json" ]]&&{ echo "$artifacts/$id.json";return;};sleep .1;done;return 1; }
send(){ local raw_id=$1 kind=$2 action source callback placement start end artifact; local id="$run_id-$raw_id" marker="PHASE9_${mode}_${raw_id}"; case $kind in get)action=hookphuzz_phase9_get_probe;source=GET;callback=hookphuzz_phase9_get_probe;placement=query;;post)action=hookphuzz_phase9_post_probe;source=POST;callback=hookphuzz_phase9_post_probe;placement=body;;cookie)action=hookphuzz_phase9_cookie_probe;source=COOKIE;callback=hookphuzz_phase9_cookie_probe;placement=cookie;;request-query)action=hookphuzz_phase9_request_probe;source=REQUEST;callback=hookphuzz_phase9_request_probe;placement=query;;request-body)action=hookphuzz_phase9_request_probe;source=REQUEST;callback=hookphuzz_phase9_request_probe;placement=body;;esac; local url="http://enabled/wp-admin/admin-ajax.php?action=$action" args=(-sS --max-time 20 -H "X-Fuzzer-Covid: $id" -H "X-Phase9-Run-ID: $run_id" -H "X-Phase9-Marker: $marker" -o "$dir/$raw_id.body" -w '%{http_code}'); [[ $placement == query ]]&&url+="&phase9_key=$marker"; [[ $placement == body ]]&&args+=(--data-urlencode "phase9_key=$marker"); [[ $placement == cookie ]]&&args+=(-b "phase9_key=$marker"); start=$(date +%s%N); [[ $(curl "${args[@]}" "$url") == 200 ]]; end=$(date +%s%N); artifact=$(wait_artifact "$id"); printf '{"run_id":"%s","id":"%s","marker":"%s","source":"%s","placement":"%s","callback":"%s","body":"%s","artifact":"%s","seconds":%.6f}\n' "$run_id" "$id" "$marker" "$source" "$placement" "$callback" "$dir/$raw_id.body" "$artifact" "$((end-start))e-9" > "$dir/$raw_id.json"; }
if [[ $mode == concurrency ]]; then kinds=(get post request-query request-body); for kind in "${kinds[@]}";do for i in $(seq 1 5);do send "p9-concurrent-$kind-$i" "$kind" & done;done;wait; php /workspace/tests/load-validate.php "$dir" 20 "$results/concurrency-summary.json" "$run_id";else kinds=(get post cookie request-query request-body);for kind in "${kinds[@]}";do for i in $(seq 1 60);do send "p9-stability-$kind-$i" "$kind";done;done;php /workspace/tests/load-validate.php "$dir" 300 "$results/stability-summary.json" "$run_id";fi
